using System.Globalization;
using System.Reflection;
using System.Text;
using System.Text.Json.Nodes;
using Xunit.Abstractions;

namespace Nro.Tests.Unit.Core.Consts;

/// <summary>
/// Compares the C# constants (<c>Nro.Core.Consts</c>) with the REAL VALUES taken from the Java classes <c>consts/*.java</c> themselves,
/// compiled with javac (tests/golden/consts.json, generated by port-csharp/tools/consts/gen_consts_golden.py
/// via reflection; not read by eye, not copied by hand).
///
/// For EVERY class and EVERY field in the golden file, the test checks via reflection on the Nro.Core assembly: the class exists and is a
/// <c>public static class</c>; the field exists; it has the right type per the mapping table (byte to sbyte, ...); the right form
/// (const / static readonly / mutable static); and the right value (strings compared code unit by code unit, arrays element by element).
/// A missing field, an extra field, a wrong value or a type mismatch all make the test fail.
/// A constant renamed to English in C# is looked up through <see cref="ConstsParity.Renamed"/> (Java name to C# name); every other constant must keep its Java name.
/// </summary>
public class ConstsParityTests
{
    private const string GoldenFileName = "consts.json";
    private const string GoldenFormat = "nro-consts-golden/1";
    private const string CsNamespace = "Nro.Core.Consts";

    /// <summary>The 20 classes of packet A-03 (matches port-csharp/tools/consts/classes.txt). There is NO ConstDataEvent (track Q).</summary>
    private static readonly string[] ExpectedClasses =
    [
        "ConstAccount", "ConstAchievement", "ConstAttribute", "ConstDailyGift", "ConstDetu", "ConstFamily",
        "ConstFont", "ConstIgnoreName", "ConstItemTemplate", "ConstMap", "ConstMenu", "ConstMob", "ConstNpc",
        "ConstPlayer", "ConstRatio", "ConstSuperRank", "ConstTask", "ConstTaskBadges", "ConstTournament",
        "ConstTranhNgocNamek",
    ];

    private readonly ITestOutputHelper _output;

    public ConstsParityTests(ITestOutputHelper output)
    {
        _output = output;
    }

    [Fact]
    public void Java_golden_has_correct_format_and_all_20_classes()
    {
        JsonObject golden = LoadGolden();

        Assert.Equal(GoldenFormat, GoldenJson.Str(golden["format"], "format"));

        JsonArray classes = GoldenJson.Arr(golden["classes"], "classes");
        string[] names = classes.Select(c => GoldenJson.Str(GoldenJson.Obj(c, "class")["name"], "name")).ToArray();
        Assert.Equal(ExpectedClasses, names);
        Assert.Equal(classes.Count, (int)GoldenJson.Int(golden["classCount"], "classCount"));

        int total = 0;
        foreach (JsonNode? c in classes)
        {
            JsonObject cls = GoldenJson.Obj(c, "class");
            int declared = (int)GoldenJson.Int(cls["fieldCount"], "fieldCount");
            int actual = GoldenJson.Arr(cls["fields"], "fields").Count;
            Assert.True(declared == actual, $"{GoldenJson.Str(cls["name"], "name")}: fieldCount {declared} differs from the actual number of fields {actual}");
            total += actual;
        }

        Assert.True(total > 0, "The golden file has no fields");
        Assert.Equal(total, (int)GoldenJson.Int(golden["fieldCount"], "fieldCount"));
    }

    [Fact]
    public void Rename_tables_only_name_real_Java_classes_and_old_class_names_are_gone()
    {
        foreach ((string javaName, string csName) in ConstRenames.Classes)
        {
            Assert.Contains(javaName, ExpectedClasses);
            Assert.True(ResolveCoreTypeRaw(javaName) is null, $"{javaName} was renamed to {csName} but a C# class with the Java name still exists");
            Assert.True(ResolveCoreTypeRaw(csName) is not null, $"{javaName} is renamed to {csName}, which does not exist");
        }

        foreach (string javaName in ConstRenames.Map.Keys)
        {
            Assert.Contains(javaName, ExpectedClasses);
        }
    }

    [Fact]
    public void Every_Java_class_and_field_matches_the_CSharp_constants()
    {
        JsonObject golden = LoadGolden();
        int declaredFields = (int)GoldenJson.Int(golden["fieldCount"], "fieldCount");
        IEnumerable<JsonObject> classes = GoldenJson.Arr(golden["classes"], "classes").Select(c => GoldenJson.Obj(c, "class"));

        ParityReport report = ConstsParity.Verify(ResolveCoreType, classes);

        _output.WriteLine($"Compared {report.ClassesChecked} classes, {report.FieldsChecked} fields (golden declares {declaredFields}).");
        Assert.True(report.Problems.Count == 0, ConstsParity.Format(report));
        Assert.True(report.FieldsChecked > 0, "No field could be compared");
        Assert.Equal(declaredFields, report.FieldsChecked);
        Assert.Equal(ExpectedClasses.Length, report.ClassesChecked);
    }

    /// <summary>
    /// The comparer must have "teeth": modify the golden data in memory for each real kind of deviation (wrong value, wrong byte sign,
    /// wrong accented character, type mismatch, flipped final, missing/extra field, ...) and then confirm that the comparer REPORTS a new error that mentions
    /// the exact field/class name that was modified. Only NEW errors compared to the unmodified version count, so this test fails if and only if the comparer is broken,
    /// and does not fail as a side effect when a real C# constant is mistyped (the comparison test above reports that).
    /// </summary>
    [Fact]
    public void Comparer_detects_every_kind_of_deviation()
    {
        MutationCase[] cases =
        [
            new("sbyte const: value off by 1", "ConstMap", "MAP_OFFLINE", c => BumpValue(Field(c, "MAP_OFFLINE"))),
            new("int const: value off by 1", "ConstRatio", "PER1000", c => BumpValue(Field(c, "PER1000"))),
            new("long const: value off by 1", "ConstTranhNgocNamek", "TIME", c => BumpValue(Field(c, "TIME"))),
            new("negative sbyte read as unsigned (-1 becomes 255)", "ConstAccount", "DEFAUT", c => Field(c, "DEFAUT")["value"] = 255L),
            new("string: one Vietnamese character loses its diacritic", "ConstSuperRank", "TEXT_DUOI_HANG", c => EditString(Field(c, "TEXT_DUOI_HANG"), s => s.Replace('ể', 'e'))),
            new("string: \\b (U+0008) changed to \\n", "ConstTournament", "TEXT_DANG_KY_THANH_CONG", c => EditString(Field(c, "TEXT_DANG_KY_THANH_CONG"), s => s.Replace('\b', '\n'))),
            new("string: extra trailing space", "ConstFont", "RED", c => EditString(Field(c, "RED"), s => s + " ")),
            new("concatenated string: one letter changed in the middle", "ConstNpc", "HUONG_DAN_CEREAL1", c => EditString(Field(c, "HUONG_DAN_CEREAL1"), s => s.Replace("Granola", "Granolb", StringComparison.Ordinal))),
            new("int array: one element changed", "ConstPlayer", "SKILL_TD", c => BumpElement(Field(c, "SKILL_TD"), 3)),
            new("int array: last element missing", "ConstTournament", "tournamentGems", c => ValueArray(Field(c, "tournamentGems")).RemoveAt(4)),
            new("string array: one element changed", "ConstTournament", "tournamentNames", c => ValueArray(Field(c, "tournamentNames"))[2] = "Siêu cấp 9"),
            new("empty array: golden has an element", "ConstIgnoreName", "IGNORE_NAME", c => ValueArray(Field(c, "IGNORE_NAME")).Add("x")),
            new("type: Java byte read as short", "ConstMob", "MOC_NHAN", c => Field(c, "MOC_NHAN")["type"] = "short"),
            new("type: Java int read as long", "ConstRatio", "PER100", c => Field(c, "PER100")["type"] = "long"),
            new("type: Java String[] read as String", "ConstTournament", "tournamentNames", c => Field(c, "tournamentNames")["type"] = "String"),
            new("form: Java is not final but C# is const", "ConstMap", "TILE_TOP", c => Field(c, "TILE_TOP")["final"] = false),
            new("form: Java is final but C# is a mutable static", "ConstNpc", "MENU_DHVT", c => Field(c, "MENU_DHVT")["final"] = true),
            new("form: Java array is not final but C# is readonly", "ConstPlayer", "HEADMONKEY", c => Field(c, "HEADMONKEY")["final"] = false),
            new("missing: Java has one more field", "ConstDetu", "KHONG_CO_TRONG_CSHARP", AddFakeField),
            new("extra: C# has a field that Java does not have", "ConstDetu", "NORMAL", c => GoldenJson.Arr(c["fields"], "fields").Remove(Field(c, "NORMAL"))),
            new("name: differs in letter case", "ConstNpc", "Calichquakhu", c => Field(c, "calichquakhu")["name"] = "Calichquakhu"),
            new("renamed: the Java name no longer matches the rename table", "ConstAchievement", "GIA_NHAP_VE_BINH_SAI", c => Field(c, "GIA_NHAP_VE_BINH")["name"] = "GIA_NHAP_VE_BINH_SAI"),
            new("class: does not exist in C#", "ConstMob", "ConstMobKhongCo", c => c["name"] = "ConstMobKhongCo"),
            new("shape: Java has a method", "ConstRatio", "ConstRatio", c => c["methods"] = new JsonArray("public static void f()")),
            new("shape: Java has a non-static field", "ConstRatio", "PER100", c => Field(c, "PER100")["static"] = false),
            new("shape: Java has a non-public field", "ConstRatio", "PER100", c => Field(c, "PER100")["access"] = "private"),
        ];

        var missed = new List<string>();
        int executed = 0;
        int skipped = 0;
        foreach (MutationCase mc in cases)
        {
            JsonObject golden = LoadGolden();
            JsonObject cls = GoldenJson.Arr(golden["classes"], "classes").Select(c => GoldenJson.Obj(c, "class"))
                .Single(c => GoldenJson.Str(c["name"], "name") == mc.Class);

            // Unmodified baseline: if a C# constant is really mistyped, the comparison test above already reports exactly that error. A mutation aimed at
            // the very spot that is already broken has nothing "new" left to detect, so it is skipped; every other mutation must still be detected.
            ParityReport baseline = ConstsParity.Verify(ResolveCoreType, [cls]);
            if (baseline.Problems.Any(p => p.Contains(mc.MustMention, StringComparison.Ordinal)))
            {
                skipped++;
                continue;
            }

            mc.Mutate(cls);
            executed++;

            ParityReport report = ConstsParity.Verify(ResolveCoreType, [cls]);
            bool detected = report.Problems.Except(baseline.Problems).Any(p => p.Contains(mc.MustMention, StringComparison.Ordinal));
            if (!detected)
            {
                missed.Add($"[{mc.Label}] was not detected (expected a new error mentioning '{mc.MustMention}')");
            }
        }

        Assert.True(missed.Count == 0, "The comparer missed: " + string.Join(" | ", missed));
        Assert.True(executed >= cases.Length / 2, $"Only {executed}/{cases.Length} mutations could run ({skipped} skipped because the C# constant was already off)");
    }

    private sealed record MutationCase(string Label, string Class, string MustMention, Action<JsonObject> Mutate);

    // A class renamed to English is looked up by its C# name (ConstRenames.Classes); the golden data keeps the Java name.
    private static Type? ResolveCoreType(string simpleName) =>
        ResolveCoreTypeRaw(ConstRenames.Classes.GetValueOrDefault(simpleName) ?? simpleName);

    private static Type? ResolveCoreTypeRaw(string csName) =>
        typeof(Nro.Core.AssemblyMarker).Assembly.GetType(CsNamespace + "." + csName, throwOnError: false);

    private static JsonObject LoadGolden()
    {
        string path = TestPaths.Golden(GoldenFileName);
        Assert.True(File.Exists(path), $"Missing {path}: run port-csharp/tools/consts/gen_consts_golden.py --cs-root <repo>");
        return JsonNode.Parse(File.ReadAllBytes(path)) as JsonObject
            ?? throw new InvalidDataException("The root of consts.json must be a JSON object");
    }

    // ---- tools for modifying the golden data in memory (used only by the sensitivity test)

    private static JsonObject Field(JsonObject cls, string name)
    {
        foreach (JsonNode? n in GoldenJson.Arr(cls["fields"], "fields"))
        {
            JsonObject f = GoldenJson.Obj(n, "field");
            if (GoldenJson.Str(f["name"], "name") == name)
            {
                return f;
            }
        }

        throw new InvalidOperationException($"The golden file has no field {name}");
    }

    private static JsonArray ValueArray(JsonObject field) => GoldenJson.Arr(field["value"], "value");

    private static void BumpValue(JsonObject field) => field["value"] = GoldenJson.Int(field["value"], "value") + 1;

    private static void BumpElement(JsonObject field, int index)
    {
        JsonArray items = ValueArray(field);
        items[index] = GoldenJson.Int(items[index], "element") + 1;
    }

    private static void EditString(JsonObject field, Func<string, string> edit)
    {
        string before = GoldenJson.Str(field["value"], "value");
        string after = edit(before);
        Assert.NotEqual(before, after);
        field["value"] = after;
    }

    private static void AddFakeField(JsonObject cls)
    {
        JsonArray fields = GoldenJson.Arr(cls["fields"], "fields");
        JsonNode clone = fields[0]!.DeepClone();
        clone["name"] = "KHONG_CO_TRONG_CSHARP";
        fields.Add(clone);
    }
}

/// <summary>The result of one comparison run.</summary>
internal sealed class ParityReport
{
    public int ClassesChecked { get; set; }

    /// <summary>The number of fields that were compared and matched completely (type, form, value).</summary>
    public int FieldsChecked { get; set; }

    public List<string> Problems { get; } = [];
}

/// <summary>Compares the Java golden data with the C# classes via reflection.</summary>
internal static class ConstsParity
{
    /// <summary>
    /// Constants renamed to English in C#: class name, then Java name to C# name (<see cref="ConstRenames.Map"/>). Every constant not listed must keep its Java name.
    /// An entry whose Java field is not in the golden file is reported, so the table cannot go stale.
    /// </summary>
    public static IReadOnlyDictionary<string, IReadOnlyDictionary<string, string>> Renamed => ConstRenames.Map;

    private static readonly IReadOnlyDictionary<string, string> NoRenames = new Dictionary<string, string>(StringComparer.Ordinal);

    private enum Form
    {
        Const,
        ReadOnly,
        Mutable,
    }

    public static ParityReport Verify(Func<string, Type?> resolve, IEnumerable<JsonObject> classes)
    {
        var report = new ParityReport();
        foreach (JsonObject cls in classes)
        {
            VerifyClass(resolve, cls, report);
        }

        return report;
    }

    public static string Format(ParityReport r)
    {
        const int show = 40;
        var sb = new StringBuilder();
        sb.Append(r.Problems.Count).Append(" deviations between the C# constants and the real Java values (").Append(r.FieldsChecked).Append(" fields matched):");
        foreach (string p in r.Problems.Take(show))
        {
            sb.AppendLine().Append("  - ").Append(p);
        }

        if (r.Problems.Count > show)
        {
            sb.AppendLine().Append("  ... and ").Append(r.Problems.Count - show).Append(" more deviations");
        }

        return sb.ToString();
    }

    private static void VerifyClass(Func<string, Type?> resolve, JsonObject cls, ParityReport report)
    {
        string name = GoldenJson.Str(cls["name"], "name");
        List<string> problems = report.Problems;
        int before = problems.Count;

        // The Java class must be a "fields-only class" to be mappable to a static class.
        if (GoldenJson.Str(cls["package"], "package") != "consts"
            || GoldenJson.Str(cls["modifiers"], "modifiers") != "public"
            || GoldenJson.Str(cls["superclass"], "superclass") != "java.lang.Object"
            || GoldenJson.Arr(cls["interfaces"], "interfaces").Count != 0
            || GoldenJson.Arr(cls["methods"], "methods").Count != 0
            || GoldenJson.Arr(cls["nestedClasses"], "nestedClasses").Count != 0)
        {
            problems.Add($"{name}: the Java class is not a 'public fields-only class' (it has methods, nested classes, interfaces or inheritance) and cannot be mapped to a static class");
        }

        Type? type = resolve(name);
        if (type is null)
        {
            problems.Add($"{name}: MISSING C# class {name} (needs a public static class in namespace Nro.Core.Consts)");
            return;
        }

        if (!type.IsPublic || !type.IsAbstract || !type.IsSealed)
        {
            problems.Add($"{name}: the C# class must be a public static class (IsPublic={type.IsPublic}, abstract={type.IsAbstract}, sealed={type.IsSealed})");
        }

        IReadOnlyDictionary<string, string> renamed = Renamed.GetValueOrDefault(name) ?? NoRenames;
        var javaNames = new HashSet<string>(StringComparer.Ordinal);
        var known = new HashSet<string>(StringComparer.Ordinal);
        foreach (JsonNode? n in GoldenJson.Arr(cls["fields"], "fields"))
        {
            JsonObject field = GoldenJson.Obj(n, "field");
            string fname = GoldenJson.Str(field["name"], "name");
            if (!javaNames.Add(fname))
            {
                problems.Add($"{name}.{fname}: the golden file has a duplicate field name");
                continue;
            }

            string csName = renamed.GetValueOrDefault(fname) ?? fname;
            if (!known.Add(csName))
            {
                problems.Add($"{name}.{fname}: the C# name {csName} is already used by another Java field (check the rename table)");
                continue;
            }

            VerifyField(type, name, csName, field, report);
        }

        foreach (string javaName in renamed.Keys)
        {
            if (!javaNames.Contains(javaName))
            {
                problems.Add($"{name}.{javaName}: the rename table lists a Java field that the golden file does not have");
            }
        }

        // The reverse direction: C# must not have extra public constants that Java does not have.
        foreach (FieldInfo fi in type.GetFields(BindingFlags.Public | BindingFlags.Static | BindingFlags.Instance | BindingFlags.DeclaredOnly))
        {
            if (!known.Contains(fi.Name))
            {
                problems.Add($"{name}.{fi.Name}: EXTRA public field in C# that Java does not have");
            }
        }

        if (problems.Count == before)
        {
            report.ClassesChecked++;
        }
    }

    private static void VerifyField(Type type, string className, string csName, JsonObject field, ParityReport report)
    {
        string name = GoldenJson.Str(field["name"], "name");
        string jtype = GoldenJson.Str(field["type"], "type");
        bool isStatic = GoldenJson.Bool(field["static"], "static");
        bool isFinal = GoldenJson.Bool(field["final"], "final");
        string access = GoldenJson.Str(field["access"], "access");
        string who = className + "." + name + (csName == name ? string.Empty : " (C# " + csName + ")");
        List<string> problems = report.Problems;

        if (access != "public" || !isStatic)
        {
            problems.Add($"{who}: Java {access}{(isStatic ? " static" : " (instance field)")} cannot be mapped to a public static constant");
            return;
        }

        Type? expectedType = MapType(jtype);
        if (expectedType is null)
        {
            problems.Add($"{who}: Java type '{jtype}' is not in the comparer's mapping table");
            return;
        }

        FieldInfo? fi = type.GetField(csName, BindingFlags.Public | BindingFlags.Static | BindingFlags.DeclaredOnly);
        if (fi is null)
        {
            problems.Add($"{who}: MISSING field in C# (Java: {(isFinal ? "final " : string.Empty)}{jtype})");
            return;
        }

        if (fi.FieldType != expectedType)
        {
            problems.Add($"{who}: wrong type: Java {jtype} needs {expectedType.Name}, C# has {fi.FieldType.Name}");
            return;
        }

        int before = problems.Count;
        Form expectedForm = !isFinal ? Form.Mutable : jtype.EndsWith("[]", StringComparison.Ordinal) ? Form.ReadOnly : Form.Const;
        Form actualForm = fi.IsLiteral ? Form.Const : fi.IsInitOnly ? Form.ReadOnly : Form.Mutable;
        if (expectedForm != actualForm)
        {
            problems.Add($"{who}: wrong declaration form: Java {(isFinal ? "final" : "non-final")} {jtype} needs {expectedForm}, C# has {actualForm}");
        }

        object? actual;
        try
        {
            actual = fi.IsLiteral ? fi.GetRawConstantValue() : fi.GetValue(null);
        }
        catch (Exception e)
        {
            problems.Add($"{who}: could not read the C# value ({e.GetType().Name})");
            return;
        }

        if (!field.ContainsKey("value"))
        {
            problems.Add($"{who}: the golden file has no value");
            return;
        }

        CompareValue(who, jtype, field["value"], actual, problems);
        if (problems.Count == before)
        {
            report.FieldsChecked++;
        }
    }

    private static Type? MapType(string jtype)
    {
        int rank = 0;
        string b = jtype;
        while (b.EndsWith("[]", StringComparison.Ordinal))
        {
            rank++;
            b = b[..^2];
        }

        Type? t = b switch
        {
            "byte" => typeof(sbyte),
            "short" => typeof(short),
            "int" => typeof(int),
            "long" => typeof(long),
            "float" => typeof(float),
            "double" => typeof(double),
            "char" => typeof(char),
            "boolean" => typeof(bool),
            "String" => typeof(string),
            _ => null,
        };

        for (int i = 0; t is not null && i < rank; i++)
        {
            t = t.MakeArrayType();
        }

        return t;
    }

    private static void CompareValue(string who, string jtype, JsonNode? expected, object? actual, List<string> problems)
    {
        if (jtype.EndsWith("[]", StringComparison.Ordinal))
        {
            CompareArray(who, jtype[..^2], expected, actual, problems);
            return;
        }

        switch (jtype)
        {
            case "byte" or "short" or "int" or "long" or "char":
                CompareInteger(who, jtype, expected, actual, problems);
                break;
            case "boolean":
                if (expected is not JsonValue bv || !bv.TryGetValue(out bool eb))
                {
                    problems.Add($"{who}: corrupt golden data (expected true/false)");
                }
                else if (actual is not bool ab)
                {
                    problems.Add($"{who}: wrong C# value type: {Describe(actual)}");
                }
                else if (eb != ab)
                {
                    problems.Add($"{who}: Java {eb}, C# {ab}");
                }

                break;
            case "float" or "double":
                CompareFloatingPoint(who, jtype, expected, actual, problems);
                break;
            case "String":
                CompareString(who, expected, actual, problems);
                break;
            default:
                problems.Add($"{who}: Java type '{jtype}' is not supported by the comparer");
                break;
        }
    }

    private static void CompareArray(string who, string elementType, JsonNode? expected, object? actual, List<string> problems)
    {
        if (expected is null)
        {
            if (actual is not null)
            {
                problems.Add($"{who}: Java null, C# {Describe(actual)}");
            }

            return;
        }

        if (expected is not JsonArray items)
        {
            problems.Add($"{who}: corrupt golden data (expected an array)");
            return;
        }

        if (actual is not Array array || array.Rank != 1)
        {
            problems.Add($"{who}: Java is an array of {items.Count} elements, C# has {Describe(actual)}");
            return;
        }

        if (array.Length != items.Count)
        {
            problems.Add($"{who}: Java array length {items.Count}, C# {array.Length}");
            return;
        }

        for (int i = 0; i < items.Count; i++)
        {
            int before = problems.Count;
            CompareValue($"{who}[{i}]", elementType, items[i], array.GetValue(i), problems);
            if (problems.Count > before)
            {
                return;
            }
        }
    }

    private static void CompareInteger(string who, string jtype, JsonNode? expected, object? actual, List<string> problems)
    {
        if (expected is not JsonValue ev || !ev.TryGetValue(out long exp))
        {
            problems.Add($"{who}: corrupt golden data (expected an integer for {jtype})");
            return;
        }

        long? act = jtype switch
        {
            "byte" => actual is sbyte v ? v : null,
            "short" => actual is short v ? v : null,
            "int" => actual is int v ? v : null,
            "long" => actual is long v ? v : null,
            "char" => actual is char v ? v : null,
            _ => null,
        };

        if (act is null)
        {
            problems.Add($"{who}: wrong C# value type (expected {jtype}): {Describe(actual)}");
        }
        else if (act.Value != exp)
        {
            problems.Add($"{who}: Java {exp}, C# {act.Value}");
        }
    }

    private static void CompareFloatingPoint(string who, string jtype, JsonNode? expected, object? actual, List<string> problems)
    {
        // The golden file stores floating-point numbers as IEEE bits in a hex string ("0x3ff8000000000000"): compare the bits, which distinguishes -0.0.
        // NaN is special: Java writes 0x7ff8..., while .NET has a NaN with different bits (negative sign); every NaN is treated as the same value.
        bool isDouble = jtype == "double";
        if (expected is not JsonValue ev || !ev.TryGetValue(out string? hex) || hex is null || !hex.StartsWith("0x", StringComparison.Ordinal)
            || !ulong.TryParse(hex.AsSpan(2), NumberStyles.AllowHexSpecifier, CultureInfo.InvariantCulture, out ulong bits)
            || hex.Length != (isDouble ? 18 : 10))
        {
            problems.Add($"{who}: corrupt golden data (expected a hex bit string of the correct length for {jtype})");
            return;
        }

        if (isDouble)
        {
            bool javaNaN = (bits & 0x7FF0000000000000UL) == 0x7FF0000000000000UL && (bits & 0x000FFFFFFFFFFFFFUL) != 0;
            if (actual is not double d)
            {
                problems.Add($"{who}: wrong C# value type: {Describe(actual)}");
            }
            else if (javaNaN ? !double.IsNaN(d) : BitConverter.DoubleToUInt64Bits(d) != bits)
            {
                problems.Add($"{who}: Java bits {hex}, C# bits 0x{BitConverter.DoubleToUInt64Bits(d):x16}");
            }
        }
        else
        {
            bool javaNaN = (bits & 0x7F800000UL) == 0x7F800000UL && (bits & 0x007FFFFFUL) != 0;
            if (actual is not float f)
            {
                problems.Add($"{who}: wrong C# value type: {Describe(actual)}");
            }
            else if (javaNaN ? !float.IsNaN(f) : BitConverter.SingleToUInt32Bits(f) != bits)
            {
                problems.Add($"{who}: Java bits {hex}, C# bits 0x{BitConverter.SingleToUInt32Bits(f):x8}");
            }
        }
    }

    private static void CompareString(string who, JsonNode? expected, object? actual, List<string> problems)
    {
        string? exp = null;
        if (expected is not null && (expected is not JsonValue ev || !ev.TryGetValue(out exp) || exp is null))
        {
            problems.Add($"{who}: corrupt golden data (expected a string)");
            return;
        }

        if (actual is not null and not string)
        {
            problems.Add($"{who}: wrong C# value type: {Describe(actual)}");
            return;
        }

        string? act = (string?)actual;
        if (!string.Equals(exp, act, StringComparison.Ordinal))
        {
            problems.Add($"{who}: strings differ: {DiffString(exp, act)}");
        }
    }

    private static string DiffString(string? java, string? cs)
    {
        if (java is null || cs is null)
        {
            return $"Java {Escape(java)} / C# {Escape(cs)}";
        }

        int n = Math.Min(java.Length, cs.Length);
        int i = 0;
        while (i < n && java[i] == cs[i])
        {
            i++;
        }

        string at(string s) => i < s.Length ? "U+" + ((int)s[i]).ToString("X4", CultureInfo.InvariantCulture) : "end of string";
        string around(string s) => Escape(s.Substring(Math.Max(0, i - 8), Math.Min(s.Length - Math.Max(0, i - 8), 24)));
        return $"Java length {java.Length} / C# {cs.Length}, differ from position {i}: Java {at(java)} \"{around(java)}\" / C# {at(cs)} \"{around(cs)}\"";
    }

    private static string Describe(object? v) => v switch
    {
        null => "null",
        string s => "string \"" + Escape(s) + "\"",
        Array a => a.GetType().Name + " of length " + a.Length.ToString(CultureInfo.InvariantCulture),
        _ => v.GetType().Name + " " + Convert.ToString(v, CultureInfo.InvariantCulture),
    };

    /// <summary>Renders a string safely in a message: printable non-ASCII characters are written as \uXXXX; truncated at 80 characters.</summary>
    private static string Escape(string? s)
    {
        if (s is null)
        {
            return "null";
        }

        var sb = new StringBuilder();
        foreach (char c in s)
        {
            if (sb.Length >= 80)
            {
                sb.Append("...");
                break;
            }

            if (c is >= ' ' and <= '~' and not '\\' and not '"')
            {
                sb.Append(c);
            }
            else
            {
                sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
            }
        }

        return sb.ToString();
    }
}

/// <summary>Reads JSON with validation: corrupt golden data throws a clear error instead of guessing.</summary>
internal static class GoldenJson
{
    public static JsonObject Obj(JsonNode? n, string what) =>
        n as JsonObject ?? throw new InvalidDataException($"Corrupt golden data: '{what}' must be an object");

    public static JsonArray Arr(JsonNode? n, string what) =>
        n as JsonArray ?? throw new InvalidDataException($"Corrupt golden data: '{what}' must be an array");

    public static string Str(JsonNode? n, string what) =>
        n is JsonValue v && v.TryGetValue(out string? s) && s is not null
            ? s
            : throw new InvalidDataException($"Corrupt golden data: '{what}' must be a string");

    public static long Int(JsonNode? n, string what) =>
        n is JsonValue v && v.TryGetValue(out long x)
            ? x
            : throw new InvalidDataException($"Corrupt golden data: '{what}' must be an integer");

    public static bool Bool(JsonNode? n, string what) =>
        n is JsonValue v && v.TryGetValue(out bool x)
            ? x
            : throw new InvalidDataException($"Corrupt golden data: '{what}' must be true/false");
}
